import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.BET2x4HF.js";var i=JSON.parse(`{"title":"mbusd","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mbusd.md","filePath":"guide/mbusd.md","lastUpdated":1787638874000}`),a={name:`guide/mbusd.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="mbusd" tabindex="-1">mbusd <a class="header-anchor" href="#mbusd" aria-label="Permalink to “mbusd”">​</a></h1><p>mbusd is an open-source Modbus TCP to Modbus RTU (RS-232/485) gateway. It presents a network of RTU servers as single TCP server.</p><p>That is a TCP server, which acts as an RTU client to get data from Modbus RTU servers. See <a href="./overview#modbus">Modbus</a> for client / server.</p><p>When you add the Sunsynk HASS repository, it includes a mbusd addon called &quot;Modbus TCP to Modbus RTU Gateway Add-on&quot;.</p><p><a href="https://github.com/kellerza/sunsynk/tree/main/hass-addon-mbusd" target="_blank" rel="noreferrer">https://github.com/kellerza/sunsynk/tree/main/hass-addon-mbusd</a></p><p>Point the Sunsynk add-on at <code>tcp://homeassistant.local:502</code> (or the host that runs mbusd). mbusd has its own wait/retry on the RS485 leg — in add-on language that is <strong>3</strong> <code>READ_ATTEMPTS</code>, <strong>500 ms</strong><code>TIMEOUT</code> (<code>-W</code>), and <strong>100 ms</strong> <code>READ_MESSAGE_SPACING</code> (<code>-R</code>). Keep that RTU wait shorter than the Sunsynk add-on&#39;s <code>TIMEOUT</code>. Comparison table: <a href="./../reference/multi-options#wait-times-by-component">Wait times by component</a>.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};